import { ref, computed } from 'vue';
export default {
  name: 'TransactionImportDialog',
  props: {
    modelValue: Boolean
  },
  emits: ['update:modelValue', 'file-submitted'],
  setup(props, {
    emit
  }) {
    const dialog = computed({
      get: () => props.modelValue,
      set: value => emit('update:modelValue', value)
    });
    const file = ref(null);
    const handleFileChange = event => {
      console.log('File selected:', event);
    };
    const closeDialog = () => {
      dialog.value = false;
      file.value = null;
    };
    const submitFile = () => {
      if (file.value) {
        emit('file-submitted', file.value);
        closeDialog();
      }
    };
    return {
      dialog,
      file,
      handleFileChange,
      closeDialog,
      submitFile
    };
  }
};
